#pragma once
// AGR plugin ABI.
//
// A plugin is a class deriving from agr::Plugin. It can be:
//   * linked statically and registered with PluginManager::addStatic() (Android, consoles);
//   * built as a shared library exporting the C entry points generated by
//     AGR_DEFINE_PLUGIN(Class) and discovered at runtime.
//
// Rules for dynamic plugins (enforced by the API version check, documented in
// docs/PLUGINS.md):
//   * built with the same compiler and engine version as the host;
//   * everything registered in onLoad (components, event handlers, pools)
//     must be unregistered in onUnload, because the code lives in the library.
#include <string>
#include <vector>

#include "agr/core/Log.hpp"
#include "agr/core/Platform.hpp"
#include "agr/core/Result.hpp"
#include "agr/core/Time.hpp"
#include "agr/scene/Reflection.hpp"

namespace agr {

class Engine;

/// Bumped whenever the Plugin interface or HostApi layout changes.
inline constexpr u32 kPluginApiVersion = 1;

struct PluginInfo {
    std::string name;
    std::string version;
    std::string description;
    std::string author;
    std::vector<std::string> dependencies;  ///< Names of plugins that must load first.
};

class Plugin {
public:
    virtual ~Plugin() = default;
    virtual PluginInfo info() const = 0;
    virtual Status onLoad(Engine& engine) = 0;
    virtual void onUnload(Engine& engine) { (void)engine; }
    virtual void onFixedUpdate(Engine& engine, const FrameTime& time) { (void)engine; (void)time; }
    virtual void onUpdate(Engine& engine, const FrameTime& time) { (void)engine; (void)time; }
};

/// Host services handed to dynamic plugins so they share the host's singletons.
struct HostApi {
    u32 apiVersion = kPluginApiVersion;
    Log::ForwardFn logWrite = nullptr;
    ComponentRegistry* components = nullptr;
};

/// Called inside the plugin library: redirects its singletons to the host.
inline void bindPluginToHost(const HostApi& host) {
    if (host.logWrite) Log::setForwarder(host.logWrite);
    if (host.components) ComponentRegistry::setInstanceOverride(host.components);
}

using PluginApiVersionFn = u32 (*)();
using PluginCreateFn = Plugin* (*)(const HostApi*);
using PluginDestroyFn = void (*)(Plugin*);

} // namespace agr

/// Exports the entry points of a dynamic plugin.
#define AGR_DEFINE_PLUGIN(PluginClass)                                                      \
    AGR_PLUGIN_EXPORT agr::u32 agrPluginApiVersion() { return agr::kPluginApiVersion; }     \
    AGR_PLUGIN_EXPORT agr::Plugin* agrCreatePlugin(const agr::HostApi* host) {              \
        if (!host || host->apiVersion != agr::kPluginApiVersion) return nullptr;            \
        agr::bindPluginToHost(*host);                                                       \
        return new PluginClass();                                                           \
    }                                                                                       \
    AGR_PLUGIN_EXPORT void agrDestroyPlugin(agr::Plugin* plugin) { delete plugin; }
